CREATE DATABASE IF NOT EXISTS auto_job_assistant_offline CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE auto_job_assistant_offline;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(160) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_preferences(user_id BIGINT UNSIGNED PRIMARY KEY,roles_json JSON NOT NULL,locations_json JSON NOT NULL,work_mode VARCHAR(30) DEFAULT 'Any',experience_level VARCHAR(50) DEFAULT 'Any',employment_type VARCHAR(50) DEFAULT 'Any',min_salary INT NULL,max_salary INT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resumes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,label VARCHAR(160) NOT NULL,storage_name VARCHAR(255) NOT NULL,original_name VARCHAR(255) NOT NULL,extracted_text LONGTEXT NOT NULL,is_active BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS saved_jobs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,job_id VARCHAR(32) NOT NULL,title VARCHAR(255) NOT NULL,company VARCHAR(255) NOT NULL,location VARCHAR(255) NOT NULL,description MEDIUMTEXT NOT NULL,skills TEXT NOT NULL,notes TEXT NOT NULL, saved_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_saved(user_id,job_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS applications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,job_id VARCHAR(32) NULL,title VARCHAR(255) NOT NULL,company VARCHAR(255) DEFAULT '',location VARCHAR(255) DEFAULT '',status ENUM('Interested','Saved','Applied','Assessment','Shortlisted','Interview Scheduled','Offer Received','Rejected','Withdrawn') DEFAULT 'Interested',date_added DATE NOT NULL,date_applied DATE NULL,resume_id BIGINT UNSIGNED NULL,cover_letter MEDIUMTEXT NOT NULL,notes TEXT NOT NULL,follow_up_date DATE NULL,confirmed_submitted BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(resume_id) REFERENCES resumes(id) ON DELETE SET NULL,INDEX(user_id,status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cover_letter_drafts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,body MEDIUMTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
